import json

# Find entries with code execution but empty output from pilot data
with open('data/math-counterfactual/pilot_50.jsonl') as f:
    entries = [json.loads(l) for l in f]

empty_code_output = []
for e in entries:
    traces = e.get('traces', e.get('counterfactual_traces', []))
    if not traces:
        continue
    for t in (traces if isinstance(traces, list) else [traces]):
        steps = t.get('steps', [])
        for s in steps:
            if s.get('type') == 'code' and s.get('output', '').strip() == '':
                code = s.get('code', s.get('content', ''))
                if code.strip():
                    empty_code_output.append({
                        'problem_id': e.get('problem_id', e.get('id', 'unknown')),
                        'code_snippet': code[:200]
                    })

print(f"Found {len(empty_code_output)} empty code outputs")
for x in empty_code_output[:5]:
    print(f"\n--- {x['problem_id']} ---")
    print(x['code_snippet'])
PYEOF

